import time
import math
import numpy as np
from scipy.optimize import differential_evolution

_DE_CONTEXT = None
_DE_DEADLINE = 0.0


def fft_full_convolve(a, b):
    n_out = len(a) + len(b) - 1
    n_fft = 1 << (n_out - 1).bit_length()
    fa = np.fft.rfft(a, n_fft)
    fb = np.fft.rfft(b, n_fft)
    return np.fft.irfft(fa * fb, n_fft)[:n_out]


def fft_correlate(a, b):
    return fft_full_convolve(a, b[::-1])


def project_to_simplex(v, target):
    v = np.asarray(v, dtype=np.float64)
    n = len(v)
    lo = float(v.min() - 1.0)
    hi = float(v.max())

    for _ in range(64):
        mid = 0.5 * (lo + hi)
        w = np.clip(v - mid, 0.0, 1.0)
        if w.sum() > target:
            lo = mid
        else:
            hi = mid

    w = np.clip(v - hi, 0.0, 1.0)
    diff = target - w.sum()
    if abs(diff) > 1e-12:
        mask = (w > 0.0) & (w < 1.0)
        if mask.any():
            w[mask] += diff / mask.sum()
        else:
            w -= diff / n
    return np.clip(w, 0.0, 1.0)


def symmetric_projection(h):
    return 0.5 * (h + h[::-1])


def make_symmetric_from_half(h_half):
    h_half = project_to_simplex(h_half, len(h_half) / 2.0)
    h = np.concatenate((h_half, h_half[::-1]))
    h = symmetric_projection(h)
    return project_to_simplex(h, len(h) / 2.0)


def evaluate_c5(h):
    h = np.asarray(h, dtype=np.float64)
    dx = 2.0 / len(h)
    overlaps = fft_correlate(h, 1.0 - h)
    return float(np.max(overlaps) * dx)


def smooth_max_value(h, beta):
    h = np.asarray(h, dtype=np.float64)
    dx = 2.0 / len(h)
    overlaps = fft_correlate(h, 1.0 - h) * dx
    maximum = float(np.max(overlaps))
    scaled = np.clip(beta * (overlaps - maximum), -700.0, 0.0)
    return float(maximum + math.log(float(np.exp(scaled).sum())) / beta)


def smooth_max_gradient(h, beta):
    h = np.asarray(h, dtype=np.float64)
    n = len(h)
    dx = 2.0 / n

    overlaps = fft_correlate(h, 1.0 - h) * dx
    maximum = float(np.max(overlaps))
    weights = np.exp(np.clip(beta * (overlaps - maximum), -700.0, 0.0))
    weights /= weights.sum()

    conv_ph = np.convolve(weights, h, mode="full")[n - 1:n - 1 + n]
    conv_qh = np.convolve(weights[::-1], h, mode="full")[n - 1:n - 1 + n]
    gradient = -(conv_ph + conv_qh) * dx

    value = float(maximum + math.log(float(np.exp(
        np.clip(beta * (overlaps - maximum), -700.0, 0.0)
    ).sum())) / beta)
    return value, gradient


def perturb_h(h, noise_scale, rng):
    candidate = np.asarray(h, dtype=np.float64) + rng.normal(
        scale=noise_scale, size=len(h)
    )
    return project_to_simplex(candidate, len(h) / 2.0)


def de_objective(x):
    if time.time() >= _DE_DEADLINE:
        return 1.0e6

    h = make_symmetric_from_half(x)
    return smooth_max_value(h, _DE_CONTEXT["beta"])


def de_callback(x, convergence=None):
    return time.time() >= _DE_DEADLINE


def differential_evolution_symmetric(n_points, seed, deadline):
    global _DE_CONTEXT
    global _DE_DEADLINE

    n_half = n_points // 2
    _DE_CONTEXT = {"beta": 30.0}
    _DE_DEADLINE = deadline

    result = differential_evolution(
        de_objective,
        bounds=[(0.0, 1.0)] * n_half,
        maxiter=2000,
        popsize=20,
        seed=seed,
        callback=de_callback,
        polish=False,
        updating="immediate",
        workers=1,
    )
    return make_symmetric_from_half(result.x)


def adam_smoothed_optimization(start_h, deadline, rng):
    h = project_to_simplex(np.asarray(start_h, dtype=np.float64), len(start_h) / 2.0)
    n = len(h)

    best_h = h.copy()
    best_c5 = evaluate_c5(best_h)

    beta_blocks = (30.0, 150.0, 600.0, 2500.0)
    beta1 = 0.9
    beta2 = 0.999
    epsilon = 1.0e-8
    lr_init = 0.2
    lr_max = 1.0
    step_number = 0

    for block_index, beta in enumerate(beta_blocks):
        if time.time() >= deadline:
            break

        first_moment = np.zeros(n, dtype=np.float64)
        second_moment = np.zeros(n, dtype=np.float64)
        learning_rate = lr_init
        current_value = smooth_max_value(h, beta)
        enforce_symmetry = block_index < 2

        for _ in range(1200):
            if time.time() >= deadline:
                break

            step_number += 1
            _, gradient = smooth_max_gradient(h, beta)
            first_moment = beta1 * first_moment + (1.0 - beta1) * gradient
            second_moment = beta2 * second_moment + (1.0 - beta2) * gradient * gradient

            corrected_first = first_moment / (1.0 - beta1 ** step_number)
            corrected_second = second_moment / (1.0 - beta2 ** step_number)
            candidate = h - learning_rate * corrected_first / (
                np.sqrt(corrected_second) + epsilon
            )
            candidate = project_to_simplex(candidate, n / 2.0)
            if enforce_symmetry:
                candidate = symmetric_projection(candidate)
                candidate = project_to_simplex(candidate, n / 2.0)

            candidate_value = smooth_max_value(candidate, beta)
            if candidate_value <= current_value:
                h = candidate
                current_value = candidate_value
                learning_rate = min(learning_rate * 1.02, lr_max)

                candidate_c5 = evaluate_c5(h)
                if candidate_c5 < best_c5:
                    best_h = h.copy()
                    best_c5 = candidate_c5
            else:
                learning_rate *= 0.5

    return best_h, best_c5


def local_swap_improvement(start_h, deadline, rng, steps=35000):
    h = project_to_simplex(np.asarray(start_h, dtype=np.float64), len(start_h) / 2.0)
    best_h = h.copy()
    best_c5 = evaluate_c5(h)
    n = len(h)

    for _ in range(steps):
        if time.time() >= deadline:
            break

        i = int(rng.integers(0, n))
        j = int(rng.integers(0, n))
        if i == j:
            continue

        delta = min(h[i], 1.0 - h[j]) * float(rng.random()) * 0.1
        if delta <= 0.0:
            continue

        h[i] -= delta
        h[j] += delta
        candidate_c5 = evaluate_c5(h)

        if candidate_c5 < best_c5:
            best_c5 = candidate_c5
            best_h = h.copy()
        else:
            h[i] += delta
            h[j] -= delta

    return best_h, best_c5


def basin_hopping(start_h, deadline, rng, steps=15000,
                  temp_start=0.01, cooling=0.995, noise_scale=0.02):
    current_h = project_to_simplex(
        np.asarray(start_h, dtype=np.float64), len(start_h) / 2.0
    )
    current_c5 = evaluate_c5(current_h)
    best_h = current_h.copy()
    best_c5 = current_c5
    temperature = temp_start

    for _ in range(steps):
        if time.time() >= deadline:
            break

        candidate_h = perturb_h(current_h, noise_scale, rng)
        candidate_c5 = evaluate_c5(candidate_h)
        accept = candidate_c5 < current_c5

        if not accept and temperature > 0.0:
            exponent = -(candidate_c5 - current_c5) / temperature
            accept = float(rng.random()) < math.exp(max(exponent, -700.0))

        if accept:
            current_h = candidate_h
            current_c5 = candidate_c5
            if current_c5 < best_c5:
                best_h = current_h.copy()
                best_c5 = current_c5

        temperature *= cooling

    return best_h, best_c5


def resize_initial_values(values, n_points):
    values = np.asarray(values, dtype=np.float64)
    if len(values) == n_points:
        return values.copy()

    x_old = np.linspace(0.0, 2.0, len(values), endpoint=False)
    x_new = np.linspace(0.0, 2.0, n_points, endpoint=False)
    return np.interp(x_new, x_old, values)


def random_symmetric_binary_start(n_points, rng):
    h = np.zeros(n_points, dtype=np.float64)
    selected = rng.choice(n_points, size=n_points // 2, replace=False)
    h[selected] = 1.0
    h = symmetric_projection(h)
    return project_to_simplex(h, n_points / 2.0)


